{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Celiprolol, a urea-containing beta-blocker with the same tert-butylamino-hydroxypropoxy aryl core, has human oral bioavailability of only 30–70% with dose-dependent, nonlinear absorption; this moderate and saturable absorption phenotype is the most transferable baseline for the query and is expected to be pushed below 20% by rifampin induction of efflux/metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pafenolol, another urea-containing beta-blocker, has absolute oral bioavailability of 27% at a 25 mg dose, increasing with dose; this demonstrates that urea-containing beta-blockers can have F near the threshold and are subject to first-pass/efflux limitation that rifampin would exacerbate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Prenalterol, a beta-blocker of the same aryloxypropanolamine class, has absolute bioavailability of about 15% after oral solution, providing direct evidence that beta-blockers in this chemical space can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Practolol has near-complete oral bioavailability (~100%), but it lacks the urea and tert-butylamine moieties and is not extensively metabolized, so its high F is not transferable to the query under rifampin.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Penbutolol has 90% oral bioavailability, but it is a highly lipophilic non-urea beta-blocker with different disposition; its high F does not outweigh the moderate-F urea-containing analogues for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low (F < 20%) for the query under rifampin co-treatment: the most transferable urea-containing beta-blocker analogues (celiprolol, pafenolol) show moderate and dose-dependent oral bioavailability (27–70%), and rifampin is expected to reduce oral bioavailability via CYP3A4/P-gp induction, pushing F below 20%; high-F analogues lack the urea/tert-butylamine features and are less transferable.",
  "evidence_gaps": [
    "No direct rifampin-interaction record for the query or an exact analogue; the magnitude of rifampin-induced reduction in F is inferred from CYP3A4/P-gp induction and moderate baseline F.",
    "Dose of the query is unspecified; rifampin effects and bioavailability may be dose-dependent, as seen with celiprolol and pafenolol."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

